using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IAsyncDisposable
{
    private readonly HttpListener listener = new();
    private readonly Uri baseAddress;
    private readonly HttpClient client;
    private Task? serving;

    public HttpPaymentGatewayTests()
    {
        var port = FreePort();
        baseAddress = new Uri($"http://127.0.0.1:{port}/");
        listener.Prefixes.Add(baseAddress.ToString());
        listener.Start();
        client = new HttpClient { BaseAddress = baseAddress };
    }

    private sealed record Captured(string Method, string Path, string? ContentType, JsonElement Body);

    private Task<Captured> Serve(int status, string body, string contentType = "application/json")
    {
        var captured = new TaskCompletionSource<Captured>();
        serving = Task.Run(async () =>
        {
            var ctx = await listener.GetContextAsync();
            using var reader = new StreamReader(ctx.Request.InputStream, Encoding.UTF8);
            var raw = await reader.ReadToEndAsync();
            captured.SetResult(new Captured(
                ctx.Request.HttpMethod,
                ctx.Request.Url!.AbsolutePath,
                ctx.Request.ContentType,
                JsonDocument.Parse(raw).RootElement.Clone()));
            ctx.Response.StatusCode = status;
            ctx.Response.ContentType = contentType;
            var bytes = Encoding.UTF8.GetBytes(body);
            await ctx.Response.OutputStream.WriteAsync(bytes);
            ctx.Response.Close();
        });
        return captured.Task;
    }

    private async Task<(AuthorizationOutcome Outcome, Captured Request)> Authorize(int status, string body)
    {
        var request = Serve(status, body);
        var outcome = await new HttpPaymentGateway(client)
            .AuthorizeAsync("ORD-7", new Money(12.50m, "eur"), CancellationToken.None);
        return (outcome, await request);
    }

    [Fact]
    public async Task The_request_is_a_JSON_POST_to_the_authorizations_endpoint()
    {
        var (_, request) = await Authorize(200, """{"status":"approved"}""");

        Assert.Equal("POST", request.Method);
        Assert.Equal("/v1/authorizations", request.Path);
        Assert.StartsWith("application/json", request.ContentType);
    }

    [Fact]
    public async Task The_request_body_carries_reference_amount_and_normalized_currency()
    {
        var (_, request) = await Authorize(200, """{"status":"approved"}""");

        Assert.Equal(
            ["amount", "currency", "reference"],
            request.Body.EnumerateObject().Select(p => p.Name).Order().ToArray());
        Assert.Equal("ORD-7", request.Body.GetProperty("reference").GetString());
        Assert.Equal(12.50m, request.Body.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", request.Body.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        var (outcome, _) = await Authorize(200, """{"status":"approved"}""");
        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        var (outcome, _) = await Authorize(200, """{"status":"declined"}""");
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        var (outcome, _) = await Authorize(200, """{"id":"a1","status":"approved","risk":{"score":3}}""");
        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Theory]
    [InlineData("{}")]
    [InlineData("""{"status":null}""")]
    [InlineData("""{"status":"APPROVED"}""")]
    [InlineData("""{"state":"approved"}""")]
    [InlineData("null")]
    public async Task An_answer_without_a_recognised_approval_is_never_treated_as_approved(string body)
    {
        var (outcome, _) = await Authorize(200, body);
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_402_refusal_is_read_as_declined()
    {
        var (outcome, _) = await Authorize(402, """{"error":"insufficient_funds"}""");
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_failures_surface_as_errors_instead_of_a_decision(int status)
    {
        var request = Serve(status, """{"status":"approved"}""");

        var ex = await Assert.ThrowsAsync<HttpRequestException>(() => new HttpPaymentGateway(client)
            .AuthorizeAsync("ORD-7", new Money(1, "EUR"), CancellationToken.None));

        Assert.Equal((HttpStatusCode)status, ex.StatusCode);
        await request;
    }

    [Fact]
    public async Task A_malformed_answer_surfaces_as_an_error()
    {
        var request = Serve(200, "<html>oops</html>");

        await Assert.ThrowsAnyAsync<JsonException>(() => new HttpPaymentGateway(client)
            .AuthorizeAsync("ORD-7", new Money(1, "EUR"), CancellationToken.None));
        await request;
    }

    public async ValueTask DisposeAsync()
    {
        client.Dispose();
        listener.Close();
        if (serving is not null) await Task.WhenAny(serving, Task.Delay(1000));
    }

    private static int FreePort()
    {
        var l = new TcpListener(IPAddress.Loopback, 0);
        l.Start();
        var port = ((IPEndPoint)l.LocalEndpoint).Port;
        l.Stop();
        return port;
    }
}
